<?php
require 'config/database.php';$pageTitle='Endereços';
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$d=[trim($_POST['label']),trim($_POST['street']),trim($_POST['city']),trim($_POST['state']),trim($_POST['zip'])];if($id){$d[]=$id;$pdo->prepare("UPDATE addresses SET label=?,street=?,city=?,state=?,zip=? WHERE id=?")->execute($d);}else{$pdo->prepare("INSERT INTO addresses(label,street,city,state,zip) VALUES(?,?,?,?,?)")->execute($d);}header('Location: addresses.php');exit;}
if(isset($_GET['delete'])){$pdo->prepare("DELETE FROM addresses WHERE id=?")->execute([(int)$_GET['delete']]);header('Location: addresses.php');exit;}
$edit=null;if(isset($_GET['edit'])){$s=$pdo->prepare("SELECT * FROM addresses WHERE id=?");$s->execute([(int)$_GET['edit']]);$edit=$s->fetch();}
$items=$pdo->query("SELECT * FROM addresses ORDER BY id DESC")->fetchAll();require 'includes/header.php';?>
<h1 class="page-title">Endereços</h1><p class="muted mb-4">Cadastre os locais de origem e destino das entregas.</p>
<div class="row g-4"><div class="col-lg-4"><div class="card content-card"><h5><?= $edit?'Editar':'Novo' ?> endereço</h5><form method="post"><input type="hidden" name="id" value="<?= $edit['id']??'' ?>"><label class="form-label mt-2">Identificação</label><input class="form-control mb-3" name="label" required placeholder="Ex.: Depósito central" value="<?= htmlspecialchars($edit['label']??'') ?>"><label class="form-label">Rua e número</label><input class="form-control mb-3" name="street" required value="<?= htmlspecialchars($edit['street']??'') ?>"><label class="form-label">Cidade</label><input class="form-control mb-3" name="city" required value="<?= htmlspecialchars($edit['city']??'') ?>"><label class="form-label">Estado (UF)</label><input class="form-control mb-3" name="state" maxlength="2" required value="<?= htmlspecialchars($edit['state']??'') ?>"><label class="form-label">CEP</label><input class="form-control mb-3" name="zip" value="<?= htmlspecialchars($edit['zip']??'') ?>"><button class="btn btn-primary w-100">Salvar endereço</button></form></div></div>
<div class="col-lg-8"><div class="card content-card"><h5 class="mb-3">Endereços cadastrados</h5><div class="table-responsive"><table class="table"><thead><tr><th>Identificação</th><th>Endereço</th><th>Ações</th></tr></thead><tbody><?php foreach($items as $a): ?><tr><td><?= htmlspecialchars($a['label']) ?></td><td><?= htmlspecialchars($a['street'].', '.$a['city'].'/'.$a['state']) ?></td><td><a href="?edit=<?= $a['id'] ?>">Editar</a> · <a class="text-danger" onclick="return confirm('Excluir?')" href="?delete=<?= $a['id'] ?>">Excluir</a></td></tr><?php endforeach; ?><?php if(!$items): ?><tr><td colspan="3" class="muted">Nenhum endereço cadastrado.</td></tr><?php endif; ?></tbody></table></div></div></div></div>
<?php require 'includes/footer.php'; ?>
